### ==========================================================================
### QUBIO - Quantum Biological Sequence Search & Assembly
### Versão Integrada: Lógica Quântica Pura + Reconstrução Biológica
### ==========================================================================

from qiskit import QuantumCircuit, transpile
from qiskit_aer import AerSimulator
from qiskit.circuit.library import MCXGate
import matplotlib.pyplot as plt
import numpy as np

# 1. Dataset & BioBloQu Structure
target_sequences = ['AAAATCTGTCATAAATTATC', 'ATTATTCTCCTTTCTTTAGT']

database_sequence = (
    ''
)

enzyme_seq = "ATGCCACGCAGTAGATGCACTGGTGCTGGCCGCCACGACCGAAAGTCTGCTGCTAA"
bio_block = "GCCACCATGGTGAGCAAGGGCGAGGCT" + "AGGAGG" + enzyme_seq + "AATAAA"

def encode_nucleotide(qc, qubit, nucleotide):
    if nucleotide == 'A': pass
    elif nucleotide == 'T': qc.x(qubit)
    elif nucleotide == 'C': qc.h(qubit); qc.x(qubit)
    elif nucleotide == 'G': qc.x(qubit); qc.h(qubit)

def nucleotide_oracle(qc, qubits, target):
    n = len(qubits)
    for i, base in enumerate(target):
        if base == 'A': qc.x(qubits[i])
        elif base == 'C': qc.h(qubits[i]); qc.x(qubits[i])
        elif base == 'G': qc.h(qubits[i])
    qc.h(qubits[-1]); qc.append(MCXGate(n-1), qubits); qc.h(qubits[-1])
    for i, base in enumerate(target):
        if base == 'A': qc.x(qubits[i])
        elif base == 'C': qc.x(qubits[i]); qc.h(qubits[i])
        elif base == 'G': qc.h(qubits[i])

def diffusion_operator(qc, n_qubits):
    qubits = list(range(n_qubits))
    qc.h(qubits); qc.x(qubits)
    qc.h(qubits[-1]); qc.append(MCXGate(n_qubits-1), qubits); qc.h(qubits[-1])
    qc.x(qubits); qc.h(qubits)

def run_quantum_assembly(targets, database):
    backend = AerSimulator()
    final_results = []
    for target in targets:
        sample = target[:5]
        n = len(sample)
        qc = QuantumCircuit(n)
        qc.h(range(n))
        nucleotide_oracle(qc, list(range(n)), sample)
        diffusion_operator(qc, n)
        qc.measure_all()
        t_qc = transpile(qc, backend)
        counts = backend.run(t_qc, shots=1024).result().get_counts()
        prob = max(counts.values()) / 1024
        new_seq = database.replace(target, bio_block)
        final_results.append((prob, target, new_seq))
    return final_results

print("--- INICIANDO BUSCA E MONTAGEM QUÂNTICA ---\n")
results = run_quantum_assembly(target_sequences, database_sequence)

# Exibição dos resultados no prompt
for i, (prob, target, seq) in enumerate(results):
    print(f"[RESULTADO {i+1}]")
    print(f"Alvo detectado: {target}")
    print(f"Probabilidade: {prob:.4f}")
    print(f"Sequência Reconstruída (BioBloQu) COMPLETA:")
    print(f"{seq}\n")

if results:
    plt.figure(figsize=(8, 5))
    prob_values = [r[0] for r in results]
    plt.bar(range(1, len(prob_values) + 1), prob_values, color='blue', alpha=0.9, label='Detected Probability')
    plt.axhline(y=1.0, color='red', linestyle='--', label='Ideal Probability = 1.0')
    plt.xlabel('Target Sequences (Scar Sites)')
    plt.ylabel('Probability')
    plt.title('Quantum Probability of Scar Site Identification')
    plt.xticks(range(1, len(prob_values) + 1), [f"Scar {i+1}" for i in range(len(prob_values))])
    plt.ylim(0, 1.1)
    plt.grid(axis='y', linestyle='--', alpha=0.7)
    plt.legend()
    plt.show()